1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 已销毁档案仍带着未解除冻结时，即使清册归属、条目快照与处理日期都合法，
10	// Open 也必须按保存记录损坏失败（ErrCorruptState）：错误指出档案编号、
11	// 未解除的冻结编号与所属清册申请编号，原文件保持原样。
12	func TestOpenRejectsActiveFreezeOnDestroyedArchive(t *testing.T) {
13		freezeReleased := func(id string) string {
14			return `{"id":"` + id + `","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-06"}`
15		}
16		freezeActive := func(id, extra string) string {
17			return `{"id":"` + id + `","reason":"诉讼","frozen_on":"2025-01-05","released":false` + extra + `}`
18		}
19		archive := func(id string, freezes string) string {
20			return `"` + id + `":{"id":"` + id + `","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":true,"manifest_id":"APP-1","freezes":[` + freezes + `]}`
21		}
22		entry := func(id string) string {
23			return `{"id":"` + id + `","category":"合同","start":"2020-01-01","end":"2025-01-10"}`
24		}
25		state := func(archivesJSON, entriesJSON string) string {
26			return `{"version":1,"archives":{` + archivesJSON + `},"manifests":{"APP-1":{"application_id":"APP-1","processed_on":"2025-01-10","entries":[` + entriesJSON + `]}}}`
27		}
28	
29		corrupt := map[string]struct {
30			state   string
31			wantAll []string // 错误信息必须全部包含
32		}{
33			"已销毁档案带一条未解除冻结": {
34				state(archive("A-1", freezeActive("F-1", "")), entry("A-1")),
35				[]string{"A-1", "F-1", "APP-1"},
36			},
37			"另一条已解除不能抵消未解除的一条": {
38				state(archive("A-1", freezeReleased("F-1")+","+freezeActive("F-2", "")), entry("A-1")),
39				[]string{"A-1", "F-2", "APP-1"},
40			},
41			"残留解除日期与原因但仍标记未解除": {
42				// 解除与否只看保存的解除标记；残留字段不能把它当作已解除。
43				state(archive("A-1",
44					freezeActive("F-1", `,"release_reason":"结案","released_on":"2025-01-06"`)),
45					entry("A-1")),
46				[]string{"A-1", "F-1", "APP-1"},
47			},
48			"多档案清册中只有第二份仍被冻结": {
49				state(archive("A-1", "")+","+archive("A-2", freezeActive("F-2", "")),
50					entry("A-1")+","+entry("A-2")),
51				[]string{"A-2", "F-2", "APP-1"},
52			},
53		}
54		for name, tc := range corrupt {
55			t.Run(name, func(t *testing.T) {
56				dir := t.TempDir()
57				writeStateFile(t, dir, tc.state)
58	
59				s, err := Open(dir)
60				if err == nil {
61					s.Close()
62					t.Fatal("已销毁档案仍带未解除冻结时不应打开成功")
63				}
64				if !errors.Is(err, ErrCorruptState) {
65					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
66				}
67				msg := err.Error()
68				for _, want := range tc.wantAll {
69					if !strings.Contains(msg, want) {
70						t.Fatalf("错误信息应指出 %q，得到 %v", want, err)
71					}
72				}
73				if name == "多档案清册中只有第二份仍被冻结" {
74					// 错误必须定位到仍被冻结的第二份，而不是只提第一份。
75					if strings.Count(msg, "A-1") > 0 {
76						t.Fatalf("不应把已合法解除的 A-1 当作问题条目，得到 %v", err)
77					}
78				}
79				if got := readStateFile(t, dir); got != tc.state {
80					t.Fatalf("打开失败后原文件被改动:\n%q", got)
81				}
82			})
83		}
84	
85		// 对照组：已销毁档案没有冻结或全部冻结均已合法解除时可正常打开，
86		// 历史与清册完整可查；尚未销毁的档案保留未解除冻结仍是合法状态。
87		t.Run("合法记录对照组", func(t *testing.T) {
88			valid := map[string]string{
89				"已销毁且没有冻结":    state(archive("A-1", ""), entry("A-1")),
90				"已销毁且冻结全部已解除": state(archive("A-1", freezeReleased("F-1")), entry("A-1")),
91			}
92			for name, content := range valid {
93				t.Run(name, func(t *testing.T) {
94					dir := t.TempDir()
95					writeStateFile(t, dir, content)
96					s, err := Open(dir)
97					if err != nil {
98						t.Fatalf("合法记录应能打开: %v", err)
99					}
100					defer s.Close()
101					if h, found, err := s.History("A-1"); err != nil || !found || !h.Destroyed || h.Manifest == nil {
102						t.Fatalf("已销毁档案的历史与清册应完整可查: found=%v err=%v %+v", found, err, h)
103					}
104					if _, found, err := s.GetManifest("APP-1"); err != nil || !found {
105						t.Fatalf("合法清册应可取回: found=%v err=%v", found, err)
106					}
107				})
108			}
109	
110			t.Run("未销毁档案带未解除冻结合法并显示阻碍", func(t *testing.T) {
111				dir := t.TempDir()
112				s, err := Open(dir)
113				if err != nil {
114					t.Fatal(err)
115				}
116				defer s.Close()
117				reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
118				if err := s.Freeze(FreezeInput{
119					ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
120				}); err != nil {
121					t.Fatal(err)
122				}
123				h, found, err := s.History("A-1")
124				if err != nil || !found {
125					t.Fatalf("未销毁档案的未解除冻结应能正常查看: found=%v err=%v", found, err)
126				}
127				if len(h.ActiveFreezes) != 1 || h.ActiveFreezes[0].ID != "F-1" {
128					t.Fatalf("历史应显示未解除冻结: %+v", h.ActiveFreezes)
129				}
130				r, err := s.Check(CheckRequest{
131					ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
132				})
133				if err != nil || r.Status != CheckBlocked ||
134					len(r.Results[0].Obstructions) != 1 ||
135					r.Results[0].Obstructions[0].Kind != ObstructionActiveFreeze {
136					t.Fatalf("销毁前核对应显示冻结阻碍: %+v err=%v", r, err)
137				}
138				if _, err := s.Destroy(DestructionRequest{
139					ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
140				}); !errors.Is(err, ErrActiveFreeze) {
141					t.Fatalf("未解除冻结仍应阻止销毁，得到 %v", err)
142				}
143			})
144		})
145	}
146	
147	// 保管库打开后保存内容才出现“已销毁档案仍带未解除冻结”的矛盾：
148	// 下一次使用有效输入查询历史、取回清册、销毁前核对与各项办理都必须按整库
149	// 记录损坏失败——即使操作的是不在该清册中的无关档案——不返回正常历史、
150	// 清册或部分核对报告，不产生业务变更，原保存内容保持原样。
151	func TestActiveFreezeOnDestroyedAfterOpenFailsAllOperations(t *testing.T) {
152		cases := map[string]func(map[string]any){
153			// 只把解除标记改回 false：解除日期与解除原因仍残留在记录里，
154			// 但只要仍标记为未解除，就不能把残留字段当作已解除。
155			"解除标记被改回未解除且残留解除信息": func(doc map[string]any) {
156				freezes := doc["archives"].(map[string]any)["A-1"].(map[string]any)["freezes"].([]any)
157				freezes[0].(map[string]any)["released"] = false
158			},
159		}
160		for name, mutate := range cases {
161			t.Run(name, func(t *testing.T) {
162				dir := t.TempDir()
163				s, err := Open(dir)
164				if err != nil {
165					t.Fatal(err)
166				}
167				defer s.Close()
168				reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
169				reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
170				if err := s.Freeze(FreezeInput{
171					ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
172				}); err != nil {
173					t.Fatal(err)
174				}
175				if err := s.Release(ReleaseInput{
176					ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-06"),
177				}); err != nil {
178					t.Fatal(err)
179				}
180				if _, err := s.Destroy(DestructionRequest{
181					ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
182				}); err != nil {
183					t.Fatal(err)
184				}
185				if _, found, err := s.GetManifest("APP-1"); err != nil || !found {
186					t.Fatalf("损坏前清册应可取回: found=%v err=%v", found, err)
187				}
188	
189				rewriteState(t, dir, mutate)
190				corruptContent := readStateFile(t, dir)
191	
192				// 重新打开必须失败，错误指出档案、冻结与所属清册申请编号。
193				s2, err := Open(dir)
194				if err == nil {
195					s2.Close()
196					t.Fatal("销毁与冻结状态矛盾时，打开必须失败")
197				}
198				if !errors.Is(err, ErrCorruptState) ||
199					!strings.Contains(err.Error(), "A-1") ||
200					!strings.Contains(err.Error(), "F-1") ||
201					!strings.Contains(err.Error(), "APP-1") {
202					t.Fatalf("打开错误应为 ErrCorruptState 并指出 A-1/F-1/APP-1，得到 %v", err)
203				}
204	
205				// 已打开实例：即使本次只操作与该清册无关的正常档案 A-2，
206				// 也必须按整库损坏失败。
207				if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
208					t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
209				}
210				if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
211					t.Fatalf("损坏后 History 必须失败且不得给出正常销毁历史: found=%v err=%v", found, err)
212				}
213				if m, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
214					t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
215				}
216				if r, err := s.Check(CheckRequest{
217					ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
218				}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
219					t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
220				}
221				if m, err := s.Destroy(DestructionRequest{
222					ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
223				}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
224					t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
225				}
226				if err := s.Register(RegisterInput{
227					ID: "A-3", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
228				}); !errors.Is(err, ErrCorruptState) {
229					t.Fatalf("损坏后 Register 必须失败: %v", err)
230				}
231				if err := s.Freeze(FreezeInput{
232					ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
233				}); !errors.Is(err, ErrCorruptState) {
234					t.Fatalf("损坏后 Freeze 必须失败: %v", err)
235				}
236				if err := s.Release(ReleaseInput{
237					ArchiveID: "A-2", FreezeID: "F-X", Reason: "结案", ReleasedOn: MustParseDate("2025-06-02"),
238				}); !errors.Is(err, ErrCorruptState) {
239					t.Fatalf("损坏后 Release 必须失败: %v", err)
240				}
241				if _, err := s.Revise(ReviseInput{
242					RevisionID: "R-9", ArchiveID: "A-2",
243					OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
244					RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
245				}); !errors.Is(err, ErrCorruptState) {
246					t.Fatalf("损坏后 Revise 必须失败: %v", err)
247				}
248	
249				// 失败不得触发修复：不自动解除冻结、不删冻结历史、不改销毁标记、不重建清册。
250				if got := readStateFile(t, dir); got != corruptContent {
251					t.Fatalf("失败后原保存内容被改动:\n%q", got)
252				}
253	
254				// 恢复解除标记后，合法记录恢复可用：清册可查、相同申请按幂等取回，
255				// 无关档案的正常业务不受影响。
256				rewriteState(t, dir, func(doc map[string]any) {
257					freezes := doc["archives"].(map[string]any)["A-1"].(map[string]any)["freezes"].([]any)
258					freezes[0].(map[string]any)["released"] = true
259				})
260				if replay, err := s.Destroy(DestructionRequest{
261					ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
262				}); err != nil || replay.ApplicationID != "APP-1" {
263					t.Fatalf("恢复后相同申请应取回原清册: %+v err=%v", replay, err)
264				}
265				if _, err := s.Destroy(DestructionRequest{
266					ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
267				}); err != nil {
268					t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
269				}
270			})
271		}
272	}
273	
274	// 一份清册收录多份档案，只有其中一份在打开后变成“已销毁但仍被冻结”：
275	// 查询另一份本来正常的成员、或只核对/办理无关档案，也必须整库失败，
276	// 不能返回另一份成员的正常历史。
277	func TestOneContradictoryManifestEntryFailsWholeVaultAfterOpen(t *testing.T) {
278		dir := t.TempDir()
279		s, err := Open(dir)
280		if err != nil {
281			t.Fatal(err)
282		}
283		defer s.Close()
284		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
285		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-01-10")
286		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
287		for _, in := range []FreezeInput{
288			{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")},
289			{ArchiveID: "A-2", FreezeID: "F-2", Reason: "协查", FrozenOn: MustParseDate("2025-01-05")},
290		} {
291			if err := s.Freeze(in); err != nil {
292				t.Fatal(err)
293			}
294		}
295		if err := s.Release(ReleaseInput{
296			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-06"),
297		}); err != nil {
298			t.Fatal(err)
299		}
300		if err := s.Release(ReleaseInput{
301			ArchiveID: "A-2", FreezeID: "F-2", Reason: "协查结束", ReleasedOn: MustParseDate("2025-01-06"),
302		}); err != nil {
303			t.Fatal(err)
304		}
305		if _, err := s.Destroy(DestructionRequest{
306			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
307			ArchiveIDs: []string{"A-1", "A-2"},
308		}); err != nil {
309			t.Fatal(err)
310		}
311	
312		// 只把 A-2 的冻结改回未解除：A-1 仍是清册里完全正常的成员，A-3 不在该清册中。
313		rewriteState(t, dir, func(doc map[string]any) {
314			freezes := doc["archives"].(map[string]any)["A-2"].(map[string]any)["freezes"].([]any)
315			freezes[0].(map[string]any)["released"] = false
316		})
317		corruptContent := readStateFile(t, dir)
318	
319		for _, id := range []string{"A-1", "A-2", "A-3"} {
320			if h, found, err := s.History(id); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
321				t.Fatalf("矛盾与 %s 无关时查询也必须整库失败: found=%v err=%v", id, found, err)
322			}
323		}
324		if _, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found {
325			t.Fatalf("清册查询必须失败: found=%v err=%v", found, err)
326		}
327		if r, err := s.Check(CheckRequest{
328			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
329		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
330			t.Fatalf("核对清册内正常成员 A-1 也不能给出可以取回/可以办理等结论: %+v err=%v", r, err)
331		}
332		if m, err := s.Destroy(DestructionRequest{
333			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
334		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
335			t.Fatalf("办理无关档案 A-3 也必须失败且不得变更: %+v err=%v", m, err)
336		}
337		if got := readStateFile(t, dir); got != corruptContent {
338			t.Fatalf("失败后原保存内容被改动:\n%q", got)
339		}
340	}
