			state(archive("A-1", freeze("F-1", `,"reason":"诉讼","frozen_on":"2025-01-05"`)) + "," +
				archive("A-2", freeze("F-2", `,"reason":"  "`))),
			[]string{"A-2", "F-2", "冻结原因", "冻结日期"},
