	}
	if len(h.Freezes) != 1 || h.Freezes[0].Reason != "诉讼" ||
		!h.Freezes[0].FrozenOn.Equal(MustParseDate("2025-01-05")) {
		t.Fatalf("原因应去除首尾空白后保存，冻结日期应保留: %+v", h.Freezes)
	}
}
